    arp: { label: 'Arp', min: 0, max: 3, def: 0, step: 1, options: ['Off', 'Major', 'Minor', 'Octave'] },
    speed: { label: 'Arp Spd', min: 10, max: 60, def: 30, unit: 'Hz' },
    sweep: { label: 'Sweep', min: -24, max: 24, def: 0, unit: 'st' },
