    sh.curve = curve;
    const env = ac.createGain();
    const g = ac.createGain(); g.gain.value = 0.3;
    o.connect(sh).connect(g).connect(env);
    o.start(t);
    const end = adsr(env.gain, t, dur, a, d, s, r);
    return { node: env, sources: [o], end };
